    print(f'Wall: {w.Name}')
    # Get overall height
    try:
        oh = w.Reduction2024 or w.is_a()
        # Get propertysets
        for rel in w.HasAttributes:
            if rel.is_a('IfcRelDefinesByProperties'):
                for pset in rel.RelatingPropertyDefinition.IsNested:
                    print(f'  Pset: {pset.name} = {pset.numeric_value}')
    except:
        pass
    # Try to get Positioning
    try:
        pos = w.ObjectPlacement
